/*************************************************
* Name:        ExpandMask
*
* Description: Sample polynomial with uniformly random coefficients
*              in [-(bound - 1), bound] by unpacking output stream of SHAKE256(seed|nonce).
*
* Arguments:   - poly *a: pointer to output polynomial
*              - const uint8_t seed[]: byte array with seed of length HBYTES
*              - uint16_t mu: 16-bit nonce
**************************************************/
void ExpandMask(poly* y, const uint8_t rho[SEEDBYTES], uint16_t mu)
{
    uint16_t r;
    uint8_t rhoprime[SEEDBYTES + 2], v[2 * a1 * b1 * n / 8];

    memcpy(rhoprime, rho, SEEDBYTES);
    rhoprime[SEEDBYTES] = mu & 0xFF;
    rhoprime[SEEDBYTES + 1] = mu >> 8;
    H(v, 2 * a0 * b0 * n / 8, rhoprime, SEEDBYTES + 2);
    loadpoly_y(y, v, a0, b0);

    for (r = 1; r <= l; r++)
    {
        rhoprime[SEEDBYTES] = (mu + r) & 0xFF;
        rhoprime[SEEDBYTES + 1] = (mu + r) >> 8;
        H(v, 2 * a1 * b1 * n / 8, rhoprime, SEEDBYTES + 2);
        loadpoly_y(y + r, v, a1, b1);
    }

    for (; r <= k + l; r++)
    {
        rhoprime[SEEDBYTES] = (mu + r) & 0xFF;
        rhoprime[SEEDBYTES + 1] = (mu + r) >> 8;
        H(v, 2 * a2 * b2 * n / 8, rhoprime, SEEDBYTES + 2);
        loadpoly_y(y + r, v, a2, b2);
    }
}

#define LOHALF(x) ((x) & 0xFFFFFFFF)
#define HIHALF(x) ((x) >> 32)
#define TOHIGH(x) ((x) << 32)

#define mul64(r, x, y)					  \
	x0 = LOHALF(x); x1 = HIHALF(x);			  \
	y0 = LOHALF(y); y1 = HIHALF(y);			  \
	s1 = x0 * y0;							  \
	s2 = x0 * y1;							  \
	s3 = x1 * y0 + HIHALF(s1) + LOHALF(s2);   \
	r[1] = x1 * y1 + HIHALF(s2) + HIHALF(s3);   \
	r[0] = LOHALF(s1) | TOHIGH(s3)

#define shift64(r, num)                  \
    if (num >= 64) { r[0] = r[1] >> (num - 64); r[1] = 0; } \
    else { r[0] = (r[0] >> num) | (r[1] << (64 - num)); r[1] >>= num; }

